INSERT OR IGNORE INTO records(id,type,data,created) VALUES('article-sainthamaruthu','article','{"title":"Sainthamaruthu, connected by the sea","slug":"sainthamaruthu-connected-by-the-sea","category":"OUR COAST","excerpt":"Meet the coastal community at the heart of our idea: a more direct connection between fishing livelihoods and everyday meals.","body":"On Sri Lanka’s eastern coast, Sainthamaruthu has a close relationship with the sea. Fishing is part of the town’s livelihood, alongside agriculture, services and trade. Behind every catch is a network of people: crews, traders, transporters and households.\n\nFisheries Connect starts with a simple idea for this community: make it easier to find a seller, ask about a catch and agree on a price. A clear profile and an honest listing can help a buyer understand who they are buying from.\n\nThe same connection should work for fishermen. A dedicated place to list available catch, follow orders and keep track of expenses brings everyday tasks together. Technology cannot replace local knowledge or the work at sea, but it can help the next conversation happen.","image":"/images/ocean-hero.png","source":"https://nada.statistics.gov.lk/index.php/catalog/42/variable/V227","published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('article-seafood','article','{"title":"A little knowledge. A better seafood basket.","slug":"a-better-seafood-basket","category":"SEAFOOD NOTES","excerpt":"Species, weight, preparation and collection: four details that make a seafood purchase easier to compare.","body":"A useful seafood listing tells you more than a price. Start with the species, the available weight and where the catch was landed. Ask the seller when it arrived and how it has been handled.\n\nCompare like with like. A wholesale reference price is not a finished retail offer. Whole fish, cleaned fish and prepared cuts may carry different charges, and a kilogram before preparation is different from a kilogram of ready-to-cook portions. Check what the advertised weight means before ordering.\n\nAgree on pickup or local delivery and review the complete total. On Fisheries Connect, an order becomes confirmed when the seller accepts it. Official market reports can provide context for the conversation; the seller’s confirmed offer is the price for your basket.","image":"/images/tuna.png","source":"https://www.cbsl.gov.lk/en/statistics/economic-indicators/price-report","published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-1','faq','{"question":"Can I explore without an account?","answer":"Yes. Browse the seafood market, compare published reference prices, read articles and check the public directories without signing in.","order":1,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-2','faq','{"question":"How do I join as a fisherman?","answer":"Choose For fishermen, then Create account. Enter your name, email, username and a new application password. Complete your fishing profile; an administrator reviews your seller details before public sales.","order":2,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-3','faq','{"question":"Do I need a Google account to sign in?","answer":"No. Use your registered email or username and your Fisheries Connect password. Gmail addresses are welcome, but there is no Google sign-in.","order":3,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-4','faq','{"question":"Are the CBSL prices the prices I pay here?","answer":"No. CBSL figures are dated reference prices for named markets. Wholesale and retail figures are shown separately. A seller’s listing, preparation charges and delivery fee determine your order total.","order":4,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-5','faq','{"question":"How do payments and delivery work?","answer":"Each basket contains catches from one seller. Pay cash on pickup or local delivery when offered by that seller. The seller must accept your order before it is confirmed.","order":5,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-6','faq','{"question":"I forgot my password. What can I do?","answer":"Contact the operator using Help & support. After checking your account details, an administrator can provide a reset link that works once and expires after 30 minutes.","order":6,"published":true}','2026-10-15T00:00:00.000Z');
INSERT OR IGNORE INTO records(id,type,data,created) VALUES('faq-7','faq','{"question":"Does the emergency feature send a rescue team?","answer":"No. It offers a call shortcut and optional location sharing. It does not dispatch rescue services. Follow the relevant authority’s emergency procedures.","order":7,"published":true}','2026-10-15T00:00:00.000Z');

